package com.shopstream.analytics;

import com.shopstream.events.PageView;
import java.util.Map;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.Branched;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.kstream.Named;
import org.apache.kafka.streams.kstream.Produced;

public class PageViewRouter {

    static final String INPUT = "page-views";
    static final String CHECKOUT = "checkout-views";
    static final String PRODUCT = "product-views";

    public static Topology buildTopology() {
        Serde<PageView> viewSerde = JsonSerde.of(PageView.class);
        StreamsBuilder builder = new StreamsBuilder();

        Map<String, KStream<String, PageView>> routes = builder
            .stream(INPUT, Consumed.with(Serdes.String(), viewSerde))
            .filter((sessionId, view) -> view != null && view.url() != null)
            .filterNot((sessionId, view) -> view.url().startsWith("/health"))
            .mapValues(PageViewRouter::withoutQueryString)
            .split(Named.as("route-"))
            .branch((sessionId, view) -> view.url().startsWith("/checkout"),
                    Branched.as("checkout"))
            .branch((sessionId, view) -> view.url().startsWith("/product/"),
                    Branched.as("product"))
            .noDefaultBranch();

        routes.get("route-checkout").to(CHECKOUT, Produced.with(Serdes.String(), viewSerde));
        routes.get("route-product").to(PRODUCT, Produced.with(Serdes.String(), viewSerde));
        return builder.build();
    }
    static PageView withoutQueryString(PageView view) {
        int q = view.url().indexOf('?');
        String path = q < 0 ? view.url() : view.url().substring(0, q);
        return new PageView(view.userId(), view.sessionId(), path, view.referrer(), view.ts());
    }
}

