class PageViewRouterTest {

    private TopologyTestDriver driver;
    private TestInputTopic<String, PageView> input;
    private TestOutputTopic<String, PageView> checkout;
    private TestOutputTopic<String, PageView> product;

    @BeforeEach
    void setUp() {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "router-test");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "dummy:9092");
        driver = new TopologyTestDriver(PageViewRouter.buildTopology(), props);

        Serde<PageView> viewSerde = JsonSerde.of(PageView.class);
        input = driver.createInputTopic(
            "page-views", Serdes.String().serializer(), viewSerde.serializer());
        checkout = driver.createOutputTopic(
            "checkout-views", Serdes.String().deserializer(), viewSerde.deserializer());
        product = driver.createOutputTopic(
            "product-views", Serdes.String().deserializer(), viewSerde.deserializer());
    }

    @AfterEach
    void tearDown() {
        driver.close();
    }
    @Test
    void routesByUrlAndStripsQueryStrings() {
        input.pipeInput("s-1", view("s-1", "/checkout/pay?step=2"));
        input.pipeInput("s-2", view("s-2", "/product/SKU-RED-SHOE-42?utm=mail"));
        input.pipeInput("s-3", view("s-3", "/health"));
        input.pipeInput("s-4", view("s-4", "/about"));

        assertEquals("/checkout/pay", checkout.readValue().url());
        assertEquals("/product/SKU-RED-SHOE-42", product.readValue().url());
        assertTrue(checkout.isEmpty());
        assertTrue(product.isEmpty());
    }

    private static PageView view(String sessionId, String url) {
        Instant ts = Instant.parse("2026-10-08T10:15:30Z");
        return new PageView("c-77", sessionId, url, "/home", ts);
    }
}

package com.shopstream.analytics;

import com.shopstream.events.Customer;
import com.shopstream.events.PageView;
import java.time.Instant;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.common.utils.Bytes;
import org.apache.kafka.streams.KeyValue;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.Grouped;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.kstream.KTable;
import org.apache.kafka.streams.kstream.Materialized;
import org.apache.kafka.streams.kstream.Produced;
import org.apache.kafka.streams.state.KeyValueStore;

public class PageViewStats {

    /** What we know about one shopping session. */
    public record SessionSummary(long views, String lastUrl, Instant lastSeen) {

        public static SessionSummary empty() {
            return new SessionSummary(0, null, null);
        }

        public SessionSummary add(PageView view) {
            boolean newest = lastSeen == null || view.ts().isAfter(lastSeen);
            return new SessionSummary(views + 1,
                newest ? view.url() : lastUrl,
                newest ? view.ts() : lastSeen);
        }
    }

    public static Topology buildTopology() {
        Serde<PageView> viewSerde = JsonSerde.of(PageView.class);
        Serde<SessionSummary> summarySerde = JsonSerde.of(SessionSummary.class);
        Serde<Customer> customerSerde = JsonSerde.of(Customer.class);
        StreamsBuilder builder = new StreamsBuilder();

        KStream<String, PageView> views =
            builder.stream("page-views", Consumed.with(Serdes.String(), viewSerde));

        // 1. count: views per URL. The key changes from sessionId to url: repartition topic.
        views.groupBy((sessionId, view) -> view.url(),
                      Grouped.with("views-by-url", Serdes.String(), viewSerde))
             .count(Materialized.as("views-per-url"))
             .toStream()
             .to("page-view-counts", Produced.with(Serdes.String(), Serdes.Long()));

        // 2. aggregate: one summary per session. The key is already sessionId: no repartition.
        views.groupByKey(Grouped.with(Serdes.String(), viewSerde))
             .aggregate(
                 SessionSummary::empty,
                 (sessionId, view, summary) -> summary.add(view),
                 Materialized.<String, SessionSummary, KeyValueStore<Bytes, byte[]>>as(
                         "session-summary-store")
                     .withKeySerde(Serdes.String())
                     .withValueSerde(summarySerde))
             .toStream()
             .to("session-summaries", Produced.with(Serdes.String(), summarySerde));

        // 3. table aggregation: customers per loyalty tier
        KTable<String, Customer> customers = builder.table("customers",
            Consumed.with(Serdes.String(), customerSerde), Materialized.as("customers-store"));
        customers.groupBy((customerId, customer) -> KeyValue.pair(customer.tier(), customer),
                          Grouped.with("customers-by-tier", Serdes.String(), customerSerde))
                 .count(Materialized.as("customers-per-tier"))
                 .toStream()
                 .to("customers-per-tier", Produced.with(Serdes.String(), Serdes.Long()));

        return builder.build();
    }
}

package com.shopstream.analytics;

import static org.junit.jupiter.api.Assertions.assertEquals;

import com.shopstream.analytics.PageViewStats.SessionSummary;
import com.shopstream.events.Customer;
import com.shopstream.events.PageView;
import java.time.Instant;
import java.util.Properties;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.TestInputTopic;
