import org.apache.kafka.streams.state.KeyValueStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class PageViewStatsTest {

    private final Serde<PageView> viewSerde = JsonSerde.of(PageView.class);
    private final Serde<Customer> customerSerde = JsonSerde.of(Customer.class);
    private TopologyTestDriver driver;

    @BeforeEach
    void setUp() {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "stats-test");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "dummy:9092");
        driver = new TopologyTestDriver(PageViewStats.buildTopology(), props);
    }

    @AfterEach
    void tearDown() {
        driver.close();
    }

    @Test
    void keepsTheNewestUrlWhenEventsArriveOutOfOrder() {
        TestInputTopic<String, PageView> input = driver.createInputTopic(
            "page-views", Serdes.String().serializer(), viewSerde.serializer());
        input.pipeInput("s-1", view("/cart", "2026-10-08T10:00:20Z"));
        input.pipeInput("s-1", view("/checkout", "2026-10-08T10:00:50Z"));
        input.pipeInput("s-1", view("/home", "2026-10-08T10:00:05Z"));      // late event

        KeyValueStore<String, SessionSummary> store =
            driver.getKeyValueStore("session-summary-store");
        assertEquals(3, store.get("s-1").views());
        assertEquals("/checkout", store.get("s-1").lastUrl());
    }

    @Test
    void movesACustomerBetweenTiers() {
        TestInputTopic<String, Customer> customers = driver.createInputTopic(
            "customers", Serdes.String().serializer(), customerSerde.serializer());
        customers.pipeInput("c-1", new Customer("Asha", "SILVER", "Pune"));
        customers.pipeInput("c-2", new Customer("Ravi", "SILVER", "Hyderabad"));
        customers.pipeInput("c-1", new Customer("Asha", "GOLD", "Pune"));

        KeyValueStore<String, Long> perTier = driver.getKeyValueStore("customers-per-tier");
        assertEquals(1L, perTier.get("SILVER").longValue());
        assertEquals(1L, perTier.get("GOLD").longValue());
    }

    private static PageView view(String url, String timestamp) {
        return new PageView("c-77", "s-1", url, "/home", Instant.parse(timestamp));
    }
}

package com.shopstream.analytics;

import com.shopstream.events.PageView;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.streams.processor.TimestampExtractor;

/** Uses the event time stored in the payload instead of the record timestamp. */
public class PageViewTimestampExtractor implements TimestampExtractor {

    @Override
    public long extract(ConsumerRecord<Object, Object> record, long partitionTime) {
        if (record.value() instanceof PageView view && view.ts() != null) {
            return view.ts().toEpochMilli();
        }
        return record.timestamp();
    }
}

package com.shopstream.analytics;

import com.shopstream.events.PageView;
import java.time.Duration;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.KeyValue;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.Grouped;
import org.apache.kafka.streams.kstream.Materialized;
import org.apache.kafka.streams.kstream.Produced;
import org.apache.kafka.streams.kstream.Suppressed;
import org.apache.kafka.streams.kstream.TimeWindows;

public class PageViewWindows {

    public static Topology buildTopology() {
        Serde<PageView> viewSerde = JsonSerde.of(PageView.class);
        TimeWindows perMinute =
            TimeWindows.ofSizeAndGrace(Duration.ofMinutes(1), Duration.ofSeconds(30));
        StreamsBuilder builder = new StreamsBuilder();

        builder.stream("page-views", Consumed.with(Serdes.String(), viewSerde)
                   .withTimestampExtractor(new PageViewTimestampExtractor()))
               .groupBy((sessionId, view) -> view.url(),
                        Grouped.with("views-by-url", Serdes.String(), viewSerde))
               .windowedBy(perMinute)
               .count(Materialized.as("views-per-minute"))
               .suppress(Suppressed.untilWindowCloses(Suppressed.BufferConfig.unbounded()))
               .toStream()
               .map((windowedUrl, count) -> KeyValue.pair(
                        windowedUrl.key() + "@" + windowedUrl.window().startTime(), count))
               .to("page-views-per-minute", Produced.with(Serdes.String(), Serdes.Long()));

        return builder.build();
    }
}

package com.shopstream.analytics;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.shopstream.events.PageView;
import java.time.Instant;
import java.util.Properties;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.KeyValue;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.TestInputTopic;
import org.apache.kafka.streams.TestOutputTopic;
import org.apache.kafka.streams.TopologyTestDriver;
import org.junit.jupiter.api.Test;

class PageViewWindowsTest {
    @Test
    void emitsOneFinalCountWhenTheWindowCloses() {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "windows-test");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "dummy:9092");
        Serde<PageView> viewSerde = JsonSerde.of(PageView.class);

        try (TopologyTestDriver driver =
                 new TopologyTestDriver(PageViewWindows.buildTopology(), props)) {
            TestInputTopic<String, PageView> input = driver.createInputTopic(
                "page-views", Serdes.String().serializer(), viewSerde.serializer());
            TestOutputTopic<String, Long> output = driver.createOutputTopic(
                "page-views-per-minute",
                Serdes.String().deserializer(), Serdes.Long().deserializer());

            input.pipeInput("s-1", view("s-1", "/cart", "2026-10-08T10:00:10Z"));
            input.pipeInput("s-2", view("s-2", "/cart", "2026-10-08T10:00:40Z"));
            assertTrue(output.isEmpty());                 // the 10:00 window is still open

            // stream time 10:01:45 passes window end plus grace (10:01:30): the window closes
            input.pipeInput("s-3", view("s-3", "/home", "2026-10-08T10:01:45Z"));
            assertEquals(KeyValue.pair("/cart@2026-10-08T10:00:00Z", 2L), output.readKeyValue());
        }
    }

    private static PageView view(String sessionId, String url, String eventTime) {
        return new PageView("c-77", sessionId, url, "/home", Instant.parse(eventTime));
    }
}
